func limitHint(ctx context.Context, v VolumeRow, free string) string {
	return t(ctx, "volume.limit.hint", "used", orDash(v.Used), "free", free)
}

func truncateText(s string, n int) string {
	if r := []rune(s); len(r) > n {
		return string(r[:n]) + "…"
	}
	return s
}

